/**
 * FileItem Component - Displays a single file
 * 
 * Responsibilities:
 * - Show file name, size, type
 * - Handle file click (download)
 * - Show file icon based on type
 * 
 * Import rules:
 * - Can import: hooks (if needed)
 * - Can import: other components
 * - Should NOT import: services, pages
 */

import React, { useState, useEffect, useRef } from 'react';
import { getFileIcon, formatFileSize, formatDate } from '../../utils/helpers';
import { filesService } from '../../services';

const FileItem = ({ 
  file, 
  onDownload, 
  onDelete, 
  viewMode = 'list',
  isSelected = false,
  onSelect,
  onShare,
  onCopyLink,
  onRename,
  onMove,
  onCopy,
  onManageAccess
}) => {
  const [isHovered, setIsHovered] = useState(false);
  const [imageUrl, setImageUrl] = useState(null);
  const [imageLoading, setImageLoading] = useState(false);
  const [imageError, setImageError] = useState(false);
  const [showContextMenu, setShowContextMenu] = useState(false);
  const contextMenuRef = useRef(null);

  // Handle both size and size_bytes field names
  const fileSize = file.size || file.size_bytes || 0;
  const mimeType = file.mime_type || file.mimeType || '';
  const isImage = mimeType.startsWith('image/');

  // Fetch image preview URL for grid view
  useEffect(() => {
    if (viewMode === 'grid' && isImage && file.id) {
      setImageLoading(true);
      setImageError(false);
      
      filesService.getSignedUrl(file.id)
        .then((response) => {
          const signedUrl = response?.data?.url || response?.url;
          if (signedUrl) {
            setImageUrl(signedUrl);
          } else {
            setImageError(true);
          }
        })
        .catch((error) => {
          console.error('Failed to load image preview:', error);
          setImageError(true);
        })
        .finally(() => {
          setImageLoading(false);
        });
    }
  }, [viewMode, isImage, file.id]);

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (contextMenuRef.current && !contextMenuRef.current.contains(event.target)) {
        setShowContextMenu(false);
      }
    };

    if (showContextMenu) {
      document.addEventListener('mousedown', handleClickOutside);
      return () => document.removeEventListener('mousedown', handleClickOutside);
    }
  }, [showContextMenu]);

  const handleFileClick = (e) => {
    // Don't trigger download if clicking on checkbox, context menu, or action buttons
    if (
      e.target.closest('.file-checkbox') || 
      e.target.closest('.file-context-menu') ||
      e.target.closest('.file-actions') || 
      e.target.closest('.btn-icon')
    ) {
      return;
    }
    // Trigger download on file click
    if (onDownload) {
      onDownload(file.id);
    }
  };

  const handleCheckboxChange = (e) => {
    e.stopPropagation();
    if (onSelect) {
      onSelect(file.id, 'file');
    }
  };

  const handleContextMenuClick = (e) => {
    e.stopPropagation();
    setShowContextMenu(!showContextMenu);
  };

  const handleContextAction = (action, e) => {
    e.stopPropagation();
    setShowContextMenu(false);
    
    switch (action) {
      case 'share':
        if (onShare) onShare(file.id, 'file');
        break;
      case 'copyLink':
        if (onCopyLink) onCopyLink(file.id, 'file');
        break;
      case 'manageAccess':
        if (onManageAccess) onManageAccess(file.id, 'file');
        break;
      case 'delete':
        if (onDelete) onDelete(file.id);
        break;
      case 'download':
        if (onDownload) onDownload(file.id);
        break;
      case 'rename':
        if (onRename) onRename(file.id, 'file', file.name);
        break;
      case 'move':
        if (onMove) onMove(file.id, 'file');
        break;
      case 'copy':
        if (onCopy) onCopy(file.id, 'file');
        break;
      case 'details':
        // Show file details modal
        window.alert(`File Details:\nName: ${file.name}\nSize: ${formatFileSize(file.size || file.size_bytes || 0)}\nType: ${file.mime_type || file.mimeType || 'Unknown'}`);
        break;
      default:
        break;
    }
  };

  if (viewMode === 'grid') {
    return (
      <div 
        className="file-item file-item-grid"
        onMouseEnter={() => setIsHovered(true)}
        onMouseLeave={() => setIsHovered(false)}
        onClick={handleFileClick}
      >
        <div className="file-item-grid-content">
          <div className="file-icon-wrapper-grid">
            {isImage && imageUrl && !imageError ? (
              <div className="file-image-preview">
                <img 
                  src={imageUrl} 
                  alt={file.name}
                  className="file-image-thumbnail"
                  onError={() => setImageError(true)}
                />
                {isHovered && (
                  <div className="file-actions-grid" onClick={(e) => e.stopPropagation()}>
                    {onDownload && (
                      <button 
                        className="btn-icon-grid" 
                        onClick={() => onDownload(file.id)}
                        title="Download"
                      >
                        <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
                          <path d="M19 12V19H5V12H3V19C3 20.1 3.9 21 5 21H19C20.1 21 21 20.1 21 19V12H19ZM13 12.67L15.59 10.09L17 11.5L12 16.5L7 11.5L8.41 10.09L11 12.67V3H13V12.67Z" fill="currentColor"/>
                        </svg>
                      </button>
                    )}
                    {onDelete && (
                      <button 
                        className="btn-icon-grid" 
                        onClick={() => onDelete(file.id)}
                        title="Delete"
                      >
                        <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
                          <path d="M6 19C6 20.1 6.9 21 8 21H16C17.1 21 18 20.1 18 19V7H6V19ZM19 4H15.5L14.5 3H9.5L8.5 4H5V6H19V4Z" fill="currentColor"/>
                        </svg>
                      </button>
                    )}
                  </div>
                )}
              </div>
            ) : (
              <>
                <div className="file-icon-grid">
                  {imageLoading ? (
                    <div className="image-loading-spinner"></div>
                  ) : (
                    getFileIcon(mimeType)
                  )}
                </div>
                {isImage && !imageError && (
                  <div className="file-badge image-badge">IMG</div>
                )}
                {mimeType === 'application/pdf' && (
                  <div className="file-badge pdf-badge">PDF</div>
                )}
                {isHovered && (
                  <div className="file-actions-grid" onClick={(e) => e.stopPropagation()}>
                    {onDownload && (
                      <button 
                        className="btn-icon-grid" 
                        onClick={() => onDownload(file.id)}
                        title="Download"
                      >
                        <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
                          <path d="M19 12V19H5V12H3V19C3 20.1 3.9 21 5 21H19C20.1 21 21 20.1 21 19V12H19ZM13 12.67L15.59 10.09L17 11.5L12 16.5L7 11.5L8.41 10.09L11 12.67V3H13V12.67Z" fill="currentColor"/>
                        </svg>
                      </button>
                    )}
                    {onDelete && (
                      <button 
                        className="btn-icon-grid" 
                        onClick={() => onDelete(file.id)}
                        title="Delete"
                      >
                        <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
                          <path d="M6 19C6 20.1 6.9 21 8 21H16C17.1 21 18 20.1 18 19V7H6V19ZM19 4H15.5L14.5 3H9.5L8.5 4H5V6H19V4Z" fill="currentColor"/>
                        </svg>
                      </button>
                    )}
                  </div>
                )}
              </>
            )}
          </div>
          <div className="file-info-grid">
            <div className="file-name-grid" title={file.name}>{file.name}</div>
            <div className="file-size-grid">{formatFileSize(fileSize)}</div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div 
      className={`file-item ${isSelected ? 'selected' : ''}`}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
      onClick={handleFileClick}
    >
      {viewMode === 'list' && (
        <div className="file-checkbox-wrapper">
          <input
            type="checkbox"
            className="file-checkbox"
            checked={isSelected}
            onChange={handleCheckboxChange}
            onClick={(e) => e.stopPropagation()}
          />
        </div>
      )}
      <div className="file-icon-wrapper">
        <div className="file-icon">{getFileIcon(mimeType)}</div>
        {mimeType.startsWith('image/') && (
          <div className="file-badge image-badge">IMG</div>
        )}
        {mimeType === 'application/pdf' && (
          <div className="file-badge pdf-badge">PDF</div>
        )}
      </div>
      <div className="file-info">
        <div className="file-name" title={file.name}>{file.name}</div>
      </div>
      <div className="file-modified">
        {file.updated_at || file.created_at ? formatDate(file.updated_at || file.created_at) : '—'}
      </div>
      <div className="file-size">
        {formatFileSize(fileSize)}
      </div>
      <div className="file-sharing">
        <span className="sharing-status">Private</span>
      </div>
      {isHovered && (
        <div className="file-actions" onClick={(e) => e.stopPropagation()}>
          {onDownload && (
            <button 
              className="btn-icon" 
              onClick={() => onDownload(file.id)}
              title="Download"
            >
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
                <path d="M19 12V19H5V12H3V19C3 20.1 3.9 21 5 21H19C20.1 21 21 20.1 21 19V12H19ZM13 12.67L15.59 10.09L17 11.5L12 16.5L7 11.5L8.41 10.09L11 12.67V3H13V12.67Z" fill="currentColor"/>
              </svg>
            </button>
          )}
          {onDelete && (
            <button 
              className="btn-icon" 
              onClick={() => onDelete(file.id)}
              title="Delete"
            >
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
                <path d="M6 19C6 20.1 6.9 21 8 21H16C17.1 21 18 20.1 18 19V7H6V19ZM19 4H15.5L14.5 3H9.5L8.5 4H5V6H19V4Z" fill="currentColor"/>
              </svg>
            </button>
          )}
        </div>
      )}
    </div>
  );
};

export default FileItem;
